// Alerts the owner on Telegram when any workflow that names this one as its error workflow fails.
// Plain text on purpose: Markdown would fail to send on error messages full of _ * [ ].
const ALERT_CHAT_ID = 8271099427;

const e = $json.execution || {};
const wf = $json.workflow || {};
// A trigger that fails to start reports under .trigger instead of .execution
const err = e.error || ($json.trigger && $json.trigger.error) || {};
const node = e.lastNodeExecuted || (err.node && err.node.name) || 'unknown';

const lines = [
  '🚨 n8n workflow failed',
  'Workflow: ' + (wf.name || wf.id || 'unknown'),
  'Node: ' + node,
  'Error: ' + String(err.message || err.description || 'no message').slice(0, 500),
  'Mode: ' + (e.mode || ($json.trigger ? 'trigger' : 'unknown'))
];
if (e.url) lines.push('Execution: ' + e.url);

return [{ json: { chatId: ALERT_CHAT_ID, text: lines.join('\n') } }];
